/**
 * A thin line that divides content (`design/components/separator.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/separator.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/separator.module.css'

export type SeparatorOrientation = NonNullable<SeparatorProps['orientation']>

/** A thin line that divides content: the inputs it takes, by the React member's prop names. */
export interface SeparatorProps {
  /**
   * The divider's text, rendered as given; the caller chooses the case, as in "OR".
   */
  label?: string
  /**
   * Vertical needs a sized flex row to stretch inside.
   */
  orientation?: 'horizontal' | 'vertical'
}

/** A thin line that divides content. */
@Component({
  selector: 'pm-separator',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<div
[attr.class]="e2()"
data-orientation="horizontal"
data-member="separator"
><!-- rule -->
<span
[attr.class]="e3()"
></span>
<!-- label -->
<span
[attr.class]="e4()"
>{{ e5() }}</span>
<!-- rule -->
<span
[attr.class]="e3()"
></span></div>} @else {<div
[attr.class]="e6()"
[attr.data-orientation]="e7()"
aria-hidden="true"
data-member="separator"
></div>}`,
})
export class Separator {
  /**
   * The divider's text, rendered as given; the caller chooses the case, as in "OR".
   */
  readonly label = input<SeparatorProps['label']>(undefined)
  /**
   * Vertical needs a sized flex row to stretch inside.
   */
  readonly orientation = input<
    Exclude<SeparatorProps['orientation'], undefined>,
    SeparatorProps['orientation']
  >('horizontal', {
    transform: (value: SeparatorProps['orientation']) =>
      value === undefined ? 'horizontal' : value,
  })
  protected readonly $ = useMember({
    events: [],
    props: { label: () => this.label(), orientation: () => this.orientation() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return this.$p.label !== undefined
  }

  protected e2() {
    if (!(this.$p.label !== undefined)) return undefined as never
    return styles.labelled
  }

  protected e3() {
    if (!(this.$p.label !== undefined)) return undefined as never
    return styles.rule
  }

  protected e4() {
    if (!(this.$p.label !== undefined)) return undefined as never
    return styles.label
  }

  protected e5() {
    if (!(this.$p.label !== undefined)) return undefined as never
    return this.$p.label
  }

  protected e6() {
    if (this.$p.label !== undefined) return undefined as never
    return styles.separator
  }

  protected e7() {
    if (this.$p.label !== undefined) return undefined as never
    return this.$p.orientation
  }
}
